var countSmaller = function(nums) {
    const ordered = Array.from(new Set(nums)).sort((a, b) => a - b);
    const rank = new Map();
    ordered.forEach((value, index) => rank.set(value, index + 1));
    const tree = new Array(ordered.length + 1).fill(0);

    const add = (index) => {
        while (index < tree.length) {
            tree[index] += 1;
            index += index & -index;
        }
    };

    const prefixSum = (index) => {
        let total = 0;
        while (index > 0) {
            total += tree[index];
            index -= index & -index;
        }
        return total;
    };

    const answer = [];
    for (let i = nums.length - 1; i >= 0; i--) {
        const index = rank.get(nums[i]);
        answer.push(prefixSum(index - 1));
        add(index);
    }

    answer.reverse();
    return answer;
};

